namespace Utils {
  /**
   * 导出的常量
   */
  export const PI = 3.14159;

  /**
   * 计算圆的面积
   * @param radius 半径
   * @returns 面积
   */
  export function calculateCircleArea(radius: number): number {
    return PI * radius * radius;
  }

  /**
   * 计算圆的周长
   * @param radius 半径
   * @returns 周长
   */
  export function calculateCircleCircumference(radius: number): number {
    return 2 * PI * radius;
  }

  /**
   * 内部使用的辅助函数（不导出）
   */
  function validateRadius(radius: number): boolean {
    return radius > 0;
  }

  /**
   * 验证并计算
   */
  export function safeCalculate(radius: number): number | null {
    if (!validateRadius(radius)) {
      console.log('Invalid radius');
      return null;
    }
    return calculateCircleArea(radius);
  }
}

