/**
 * 基础条件类型
 * 根据类型决定返回类型
 */
type IsString<T> = T extends string ? true : false;

/**
 * 嵌套条件类型
 */
type TypeName<T> =
  T extends string ? 'string' :
  T extends number ? 'number' :
  T extends boolean ? 'boolean' :
  T extends undefined ? 'undefined' :
  T extends Function ? 'function' :
  'object';

/**
 * 分布式条件类型
 * 当T是联合类型时，条件类型会分布到每个成员
 */
type ToArray<T> = T extends any ? T[] : never;
type ToArrayNonDist<T> = [T] extends [any] ? T[] : never;

/**
 * 实用条件类型：排除null和undefined
 */
type NonNullable<T> = T extends null | undefined ? never : T;

/**
 * 实用条件类型：提取函数类型
 */
type ExtractFunction<T> = T extends (...args: any[]) => any ? T : never;

/**
 * 实用条件类型：排除函数类型
 */
type ExcludeFunction<T> = T extends (...args: any[]) => any ? never : T;

/**
 * 推断类型
 * infer关键字用于推断类型
 */
type ReturnType<T> = T extends (...args: any[]) => infer R ? R : any;

type Parameters<T> = T extends (...args: infer P) => any ? P : never;

/**
 * 解包Promise类型
 */
type UnwrapPromise<T> = T extends Promise<infer U> ? U : T;

// 测试类型
type A = IsString<string>; // true
type B = IsString<number>; // false

type T1 = TypeName<string>; // 'string'
type T2 = TypeName<number>; // 'number'
type T3 = TypeName<boolean>; // 'boolean'

type StrArr = ToArray<string | number>; // string[] | number[]

type NonNull = NonNullable<string | null | undefined>; // string

function greet(name: string): string {
  return `Hello, ${name}!`;
}

type GreetReturn = ReturnType<typeof greet>; // string
type GreetParams = Parameters<typeof greet>; // [string]

type PromiseResult = UnwrapPromise<Promise<number>>; // number

