/**
 * 基础映射类型
 * 将所有属性变为可选
 */
type MyPartial<T> = {
  [P in keyof T]?: T[P];
};

/**
 * 将所有属性变为必选
 */
type MyRequired<T> = {
  [P in keyof T]-?: T[P];
};

/**
 * 将所有属性变为只读
 */
type MyReadonly<T> = {
  readonly [P in keyof T]: T[P];
};

/**
 * 创建一个所有属性都可写的类型
 */
type MyMutable<T> = {
  -readonly [P in keyof T]: T[P];
};

/**
 * Pick类型
 * 从T中选择一组属性
 */
type MyPick<T, K extends keyof T> = {
  [P in K]: T[P];
};

/**
 * Omit类型
 * 从T中排除一组属性
 */
type MyOmit<T, K extends keyof any> = MyPick<T, Exclude<keyof T, K>>;

/**
 * Record类型
 * 创建一个属性名为K，属性值为T的类型
 */
type MyRecord<K extends keyof any, T> = {
  [P in K]: T;
};

/**
 * 示例接口
 */
