/**
 * 使用泛型约束创建工厂函数
 */
type Constructor<T> = new (...args: any[]) => T;

function createInstance<T>(ctor: Constructor<T>, ...args: any[]): T {
  return new ctor(...args);
}

/**
 * 泛型约束与默认类型
 */
interface ApiResponse<T extends object = { data: unknown }> {
  status: number;
  message: string;
  payload: T;
}

/**
 * 多重约束
 */
interface Identifiable {
  id: string | number;
}

interface Timestamped {
  createdAt: Date;
  updatedAt: Date;
}

function saveEntity<T extends Identifiable & Timestamped>(entity: T): T {
