  console.log(`Created at: ${entity.createdAt}`);
  return entity;
}

/**
 * 条件泛型约束
 */
type Flatten<T> = T extends Array<infer U> ? U : T;

/**
 * 递归泛型约束
 */
interface TreeNode {
  value: number;
  children?: TreeNode[];
}

function traverseTree<T extends TreeNode>(node: T, callback: (node: T) => void): void {
  callback(node);
  if (node.children) {
    node.children.forEach(child => traverseTree(child as T, callback));
  }
}

